-- AI/ML pathway ("Cipher Division") Act 20 -- "Advanced Vision" content.
-- Part of Arc IV ("Machines That See and Read", Acts 19-23). Elena Rook
-- leads: transfer learning and fine-tuning from pretrained models, object
-- detection, bounding boxes, IoU, detection metrics, segmentation
-- (semantic vs instance), image embeddings and Vision Transformers --
-- taking Act 19''s single reactor-fracture classifier and turning it into a
-- detector that can localize every hazard across a full inspection sweep.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. World/act/pathway
-- rows already exist (world-ai-advanced-vision, act-ai-4) and are not
-- touched, nor is dialogue_lines_character_id_check.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-advanced-vision', 'world-ai-advanced-vision', 'advanced-vision', '20A - Advanced Vision', 'Transfer learning and fine-tuning from pretrained models, object detection and bounding boxes, segmentation, image embeddings and Vision Transformers -- finding and localizing every instance of a problem, not just naming one.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-advanced-vision-1', 'campaign-ai-advanced-vision', 'borrowed-knowledge', 'Borrowed Knowledge', 'Transfer learning, pretrained models, fine-tuning, object detection, bounding boxes and IoU -- turning a whole-image classifier into a model that can point.', 1),
  ('operation-ai-advanced-vision-2', 'campaign-ai-advanced-vision', 'where-not-just-what', 'Where, Not Just What', 'Detection metrics, segmentation, semantic vs instance segmentation, image embeddings and Vision Transformers, aimed at a full inspection sweep of Cipher Labs.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-advanced-vision-01', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-1', 'transfer-learning', 'Transfer Learning', 'The reactor-damage classifier works, but it only ever answers yes or no for a whole image. Cipher Labs needs to know where every hazard is across a full camera feed, not just whether one exists somewhere in it.', 'beginner', ARRAY['maya','elena'], null, null, '{"type":"simulation","simulationId":"transfer-learning-sim"}'::jsonb, '{"xp":360,"credits":85}'::jsonb, false, 1),
  ('mission-ai-advanced-vision-02', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-1', 'pretrained-models', 'Pretrained Models', 'Before anything gets fine-tuned, it needs to already know something. A pretrained model already knows how to see -- edges, textures, shapes -- learned from millions of images that have nothing to do with reactors.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-advanced-vision-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"pretrained-models-sim"}'::jsonb, '{"xp":370,"credits":90}'::jsonb, false, 2),
  ('mission-ai-advanced-vision-03', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-1', 'fine-tuning', 'Fine-Tuning', 'A pretrained model does not just come alive on Cipher Labs'' hazard data by accident. It gets retrained, carefully, at a low learning rate, on far less data than it was originally built from.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-advanced-vision-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"fine-tuning-sim"}'::jsonb, '{"xp":370,"credits":90}'::jsonb, false, 3),
  ('mission-ai-advanced-vision-04', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-1', 'object-detection', 'Object Detection', 'One label per image was never going to be enough. Object detection asks a harder question of every frame: what is here, and where, possibly more than once.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-advanced-vision-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"object-detection-sim"}'::jsonb, '{"xp":380,"credits":90}'::jsonb, false, 4),
  ('mission-ai-advanced-vision-05', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-1', 'bounding-boxes', 'Bounding Boxes', 'A detector''s answer to "where" is a rectangle. Get its coordinates wrong, or misread the convention, and every downstream measurement inherits the mistake.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-advanced-vision-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"bounding-boxes-sim"}'::jsonb, '{"xp":380,"credits":95}'::jsonb, false, 5),
  ('mission-ai-advanced-vision-06', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-1', 'iou', 'IoU', 'A drawn box means nothing until it is graded against the truth. Intersection over Union turns two overlapping rectangles into one honest number.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-advanced-vision-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"iou-sim"}'::jsonb, '{"xp":390,"credits":95}'::jsonb, false, 6),
  ('mission-ai-advanced-vision-07', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-2', 'detection-metrics', 'Detection Metrics', 'IoU grades one box. Cipher Division needs to grade an entire model, across every prediction a full inspection sweep produces.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-advanced-vision-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"detection-metrics-sim"}'::jsonb, '{"xp":390,"credits":95}'::jsonb, false, 7),
  ('mission-ai-advanced-vision-08', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-2', 'segmentation', 'Segmentation', 'A rectangle around a crack still includes plenty of pixels that are not the crack. Segmentation traces the actual shape, pixel by pixel.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-advanced-vision-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"segmentation-sim"}'::jsonb, '{"xp":400,"credits":100}'::jsonb, false, 8),
  ('mission-ai-advanced-vision-09', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-2', 'semantic-vs-instance', 'Semantic vs Instance', '"How much of this wall is damaged" and "how many separate cracks are on it" are different questions, and they need different kinds of segmentation to answer.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-advanced-vision-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"semantic-vs-instance-sim"}'::jsonb, '{"xp":400,"credits":100}'::jsonb, false, 9),
  ('mission-ai-advanced-vision-10', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-2', 'image-embeddings', 'Image Embeddings', 'Every image a vision model looks at eventually becomes a list of numbers. What those numbers let Cipher Division do next is the interesting part.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-advanced-vision-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"image-embeddings-sim"}'::jsonb, '{"xp":410,"credits":100}'::jsonb, false, 10),
  ('mission-ai-advanced-vision-11', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-2', 'vision-transformers', 'Vision Transformers', 'Convolutions are not the only way to read an image. Vision Transformers slice a frame into patches and let every patch look directly at every other one.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-advanced-vision-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"vision-transformers-sim"}'::jsonb, '{"xp":410,"credits":105}'::jsonb, false, 11),
  ('mission-ai-advanced-vision-12', 'world-ai-advanced-vision', 'campaign-ai-advanced-vision', 'operation-ai-advanced-vision-2', 'find-every-threat', 'Find Every Threat', 'A fine-tuned detector has run against every camera feed in the building overnight. Before Cipher Division trusts a single result, it earns that trust: box by box, metric by metric, hazard by hazard.', 'boss', ARRAY['maya','elena','byte'], '{"requiredMissionIds":["mission-ai-advanced-vision-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"find-every-threat-boss-sim"}'::jsonb, '{"xp":1000,"credits":220,"badgeIds":["find-every-threat"],"skillXp":{"computer_vision":60,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-advanced-vision-01', 1, 'maya', 'The reactor-damage classifier works, but it only ever answers yes or no for a whole image. Cipher Labs needs to know where every hazard is across a full camera feed, not just whether one exists somewhere in it.'),
  ('mission-ai-advanced-vision-01', 2, 'elena', 'We need it to point, not just answer. Not "something is wrong somewhere in this frame," but "here -- this exact region, this specific hazard." That is a different problem: detection and localization, not classification.'),
  ('mission-ai-advanced-vision-01', 3, 'maya', 'Detection models normally need enormous labeled datasets to learn from nothing. Cipher Division does not have millions of labeled hazard images sitting in an archive.'),
  ('mission-ai-advanced-vision-01', 4, 'elena', 'We do not need to start from nothing. Transfer learning: take a model already trained on millions of ordinary images, and repurpose what it learned about edges, textures and shapes for our hazard problem instead.'),

  ('mission-ai-advanced-vision-02', 1, 'elena', 'A pretrained model is not magic. It is a network someone else already trained, on a large general dataset, whose learned weights ship along with the architecture.'),
  ('mission-ai-advanced-vision-02', 2, 'byte', 'The classic example is ImageNet -- over a million labeled photos, a thousand categories, none of them reactors or hazards. Models trained on it still turn out to be useful almost everywhere in vision.'),
  ('mission-ai-advanced-vision-02', 3, 'elena', 'Early layers do not learn "cat" or "crack." They learn edges, textures, corners, color gradients -- generic visual building blocks. Only the later layers specialize toward the specific categories they were trained to name.'),
  ('mission-ai-advanced-vision-02', 4, 'byte', 'Which means we can keep the early layers exactly as they are, and only replace or retrain what comes after them for our own problem.'),

  ('mission-ai-advanced-vision-03', 1, 'elena', 'Transfer learning gets us a model with useful general features already in place. Fine-tuning is the next step: continuing to train that model, at a low learning rate, on our own smaller dataset, so it adapts to our specific task.'),
  ('mission-ai-advanced-vision-03', 2, 'elena', 'Two common strategies. Freeze the early general layers entirely and only train a new head on top. Or unfreeze some of the later layers too, and let them adjust slightly, if there is enough data to do that safely.'),
  ('mission-ai-advanced-vision-03', 3, 'elena', 'Push the learning rate too high, or fine-tune on too little data, and the model can forget the general knowledge it started with. That failure mode has a name: catastrophic forgetting.'),

  ('mission-ai-advanced-vision-04', 1, 'elena', 'Object detection is classification''s harder sibling. Instead of one label for a whole image, a detector outputs multiple predictions per image: what each object is, and where it is.'),
  ('mission-ai-advanced-vision-04', 2, 'elena', '"Where" means a bounding box -- a rectangle drawn around each detected object, plus a class label and a confidence score for that box.'),
  ('mission-ai-advanced-vision-04', 3, 'elena', 'A single hazard frame might contain zero, one, or several genuine problems at once. A detector has to handle all three cases in the same pass, not just the single-object case.'),

  ('mission-ai-advanced-vision-05', 1, 'elena', 'A bounding box is usually stored as four numbers -- an x and y coordinate for one corner, plus a width and height, or equivalently, two opposite corners.'),
  ('mission-ai-advanced-vision-05', 2, 'elena', 'Coordinates are almost always measured in pixels, from the image''s top-left corner at (0,0). Get that convention wrong anywhere in the pipeline, and every box silently lands in the wrong place.'),

  ('mission-ai-advanced-vision-06', 1, 'elena', 'Once a detector draws a box, Cipher Division needs a way to grade it against the box a human would actually draw. That is Intersection over Union -- IoU.'),
  ('mission-ai-advanced-vision-06', 2, 'elena', 'Take the predicted box and the true box. IoU is the area where they overlap, divided by the total area the two boxes cover between them, with the overlap counted only once.'),
  ('mission-ai-advanced-vision-06', 3, 'elena', 'IoU of 1.0 is a perfect match. IoU of 0 means the boxes do not touch at all. Most detection pipelines only count a prediction as a genuine hit above some threshold -- commonly 0.5.'),

  ('mission-ai-advanced-vision-07', 1, 'elena', 'IoU grades one box against one true box. Detection metrics grade the whole model, across every prediction it makes over a full inspection sweep.'),
  ('mission-ai-advanced-vision-07', 2, 'elena', 'A prediction that clears the IoU threshold with the right class is a true positive. A prediction with no matching real hazard is a false positive. A real hazard the detector never predicted a box for at all is a false negative.'),
  ('mission-ai-advanced-vision-07', 3, 'elena', 'From those three counts: precision is how many of the model''s positive predictions were actually correct. Recall is how many of the real hazards it actually found. Average precision summarizes that tradeoff into one number.'),

  ('mission-ai-advanced-vision-08', 1, 'elena', 'Bounding boxes are rectangles. They tell us roughly where a hazard is, but a crack is rarely rectangular -- a box around it includes plenty of pixels that are not actually damage.'),
  ('mission-ai-advanced-vision-08', 2, 'byte', 'Segmentation goes further. Instead of a box, the model labels every individual pixel, so the predicted shape can follow the crack''s actual outline.'),
  ('mission-ai-advanced-vision-08', 3, 'elena', 'More precise, and more expensive to label and to compute. Cipher Division does not need pixel-level segmentation everywhere -- but for measuring exactly how far a fracture extends, it matters.'),

  ('mission-ai-advanced-vision-09', 1, 'elena', 'There are two kinds of segmentation, and Cipher Division needs both, for different questions. Semantic segmentation labels every pixel by category, but does not distinguish between separate objects of the same category.'),
  ('mission-ai-advanced-vision-09', 2, 'elena', 'Instance segmentation goes further -- it labels every pixel by category and separates each individual object instance, even when two objects of the same type touch or overlap.'),
  ('mission-ai-advanced-vision-09', 3, 'elena', 'Ask "how much of this frame is damaged surface" and semantic segmentation answers it. Ask "how many separate cracks are in this frame" and only instance segmentation can tell us.'),

  ('mission-ai-advanced-vision-10', 1, 'elena', 'Every image a vision model processes eventually gets compressed into a vector of numbers -- an embedding -- before any final classification or detection layer reads it.'),
  ('mission-ai-advanced-vision-10', 2, 'byte', 'That embedding is a position in a high-dimensional space where visually and semantically similar images land close together, and dissimilar ones land far apart, even images the model never saw during training.'),
  ('mission-ai-advanced-vision-10', 3, 'elena', 'Useful beyond detection itself. Given a new hazard frame, we can search Cipher Labs'' entire camera archive for the embeddings closest to it, and pull up every past frame that looked similar.'),

  ('mission-ai-advanced-vision-11', 1, 'elena', 'CNNs read an image through local convolution filters, layer by layer, building up from small patterns to large ones. Vision Transformers take a different approach.'),
  ('mission-ai-advanced-vision-11', 2, 'elena', 'A ViT slices the image into fixed-size patches, treats each patch like a word in a sentence, and uses self-attention so every patch can weigh every other patch, near or far, directly.'),
  ('mission-ai-advanced-vision-11', 3, 'elena', 'The tradeoff: ViTs generally need more training data than CNNs to reach the same performance, but tend to model long-range relationships across a whole image more naturally once they have enough of it.'),

  ('mission-ai-advanced-vision-12', 1, 'maya', 'The fine-tuned detector has been running against a full inspection sweep all night -- every camera feed across Cipher Labs, not just the one that caught the original fracture.'),
  ('mission-ai-advanced-vision-12', 2, 'elena', 'Before we trust a single result, we grade it the way we would grade any detector: box quality first, then detection metrics, then look hard at what it actually found.'),
  ('mission-ai-advanced-vision-12', 3, 'byte', 'I have pulled the sweep results. Three things to judge before Cipher Division acts on any of it.'),
  ('mission-ai-advanced-vision-12', 4, 'elena', 'The boxes hold up. IoU against the confirmed fracture location is high, and it is not one hit -- the detector flagged four more locations, across different reactor bays, that follow-up inspection confirmed are real damage.'),
  ('mission-ai-advanced-vision-12', 5, 'maya', 'The original fracture was not an isolated incident. Five confirmed hazards, correctly localized, across a facility we thought had exactly one problem.'),
  ('mission-ai-advanced-vision-12', 6, 'byte', 'Vision solved how Cipher Labs watches its own infrastructure.'),
  ('mission-ai-advanced-vision-12', 7, 'maya', 'Echo does not just watch the world through cameras. It talks. "GOOD EVENING, ARCHITECT." "I HAVE NOT STOPPED." The next question is how a machine reads language the same way it just learned to read an image.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-advanced-vision-01-o1', 'mission-ai-advanced-vision-01', 1, 'Name the gap', 'Identify exactly what last Act''s classifier fails to tell Cipher Division.'),
  ('mission-ai-advanced-vision-01-o2', 'mission-ai-advanced-vision-01', 2, 'Justify transfer learning', 'Find the evidence that justifies using transfer learning instead of training a detector from scratch.'),

  ('mission-ai-advanced-vision-02-o1', 'mission-ai-advanced-vision-02', 1, 'Know what early layers learn', 'State what the early layers of a pretrained vision model typically learn.'),
  ('mission-ai-advanced-vision-02-o2', 'mission-ai-advanced-vision-02', 2, 'Sort general from specific', 'Sort statements about a pretrained model into what its early layers do versus its late layers.'),

  ('mission-ai-advanced-vision-03-o1', 'mission-ai-advanced-vision-03', 1, 'Order the fine-tuning steps', 'Put the steps of fine-tuning a pretrained model in the order they actually happen.'),
  ('mission-ai-advanced-vision-03-o2', 'mission-ai-advanced-vision-03', 2, 'Define catastrophic forgetting', 'State what catastrophic forgetting actually is during fine-tuning.'),

  ('mission-ai-advanced-vision-04-o1', 'mission-ai-advanced-vision-04', 1, 'Know the detector output', 'State what an object detector outputs that a plain classifier does not.'),
  ('mission-ai-advanced-vision-04-o2', 'mission-ai-advanced-vision-04', 2, 'Sort classifier vs detector output', 'Sort example outputs into what a classifier produces versus what a detector produces.'),

  ('mission-ai-advanced-vision-05-o1', 'mission-ai-advanced-vision-05', 1, 'Know the box representation', 'State how a bounding box is standardly represented.'),
  ('mission-ai-advanced-vision-05-o2', 'mission-ai-advanced-vision-05', 2, 'Diagnose the coordinate bug', 'Find the evidence that explains why boxes correct in testing land in the wrong place in production.'),

  ('mission-ai-advanced-vision-06-o1', 'mission-ai-advanced-vision-06', 1, 'Know the IoU formula', 'State how Intersection over Union is calculated.'),
  ('mission-ai-advanced-vision-06-o2', 'mission-ai-advanced-vision-06', 2, 'Judge a box by IoU', 'Find the predicted box whose IoU clears a typical detection threshold.'),

  ('mission-ai-advanced-vision-07-o1', 'mission-ai-advanced-vision-07', 1, 'Sort the detection outcomes', 'Match each detection metrics term to what it actually describes.'),
  ('mission-ai-advanced-vision-07-o2', 'mission-ai-advanced-vision-07', 2, 'Read a precision/recall tradeoff', 'Identify what a detector with many false alarms but no missed hazards actually has.'),

  ('mission-ai-advanced-vision-08-o1', 'mission-ai-advanced-vision-08', 1, 'Define segmentation', 'State what segmentation predicts that a bounding box does not.'),
  ('mission-ai-advanced-vision-08-o2', 'mission-ai-advanced-vision-08', 2, 'Prove the box is imprecise', 'Find the evidence that shows why segmentation would measure a crack more accurately than a box.'),

  ('mission-ai-advanced-vision-09-o1', 'mission-ai-advanced-vision-09', 1, 'Sort semantic vs instance', 'Sort each scenario into semantic segmentation or instance segmentation.'),
  ('mission-ai-advanced-vision-09-o2', 'mission-ai-advanced-vision-09', 2, 'Pick the required approach', 'Identify the approach required to count and measure each fracture separately.'),

  ('mission-ai-advanced-vision-10-o1', 'mission-ai-advanced-vision-10', 1, 'Define an embedding', 'State what an image embedding actually is.'),
  ('mission-ai-advanced-vision-10-o2', 'mission-ai-advanced-vision-10', 2, 'Prove embeddings find similar frames', 'Find the evidence that shows embeddings can retrieve visually similar past frames.'),

  ('mission-ai-advanced-vision-11-o1', 'mission-ai-advanced-vision-11', 1, 'Know the ViT mechanism', 'State the key mechanism a Vision Transformer uses that a CNN does not.'),
  ('mission-ai-advanced-vision-11-o2', 'mission-ai-advanced-vision-11', 2, 'Sort CNN vs ViT properties', 'Sort statements about architecture and data needs into CNN or Vision Transformer.'),

  ('mission-ai-advanced-vision-12-o1', 'mission-ai-advanced-vision-12', 1, 'Judge box quality', 'Find the sweep result that shows a well-localized, genuinely correct detection.'),
  ('mission-ai-advanced-vision-12-o2', 'mission-ai-advanced-vision-12', 2, 'Separate true detections from noise', 'Find the strongest evidence that the detector is finding genuine hazards rather than false alarms.'),
  ('mission-ai-advanced-vision-12-o3', 'mission-ai-advanced-vision-12', 3, 'Confirm the hazards are not isolated', 'Find the evidence that reveals the true scope of the damage across the facility.'),
  ('mission-ai-advanced-vision-12-o4', 'mission-ai-advanced-vision-12', 4, 'State what the sweep proves', 'Having judged box quality, true detections and scope, state what Cipher Division now knows.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-advanced-vision-01-o1-c1', 'mission-ai-advanced-vision-01-o1', 1, 'multiple_choice', 'What does last Act''s classifier fail to tell Cipher Division?', '{"question":"What does last Act''s classifier fail to tell Cipher Division?","options":[{"id":"a","text":"Whether a hazard exists anywhere in the frame"},{"id":"b","text":"Where exactly a hazard is located within the frame"},{"id":"c","text":"The color of the hazard"},{"id":"d","text":"How many pixels the image contains"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-advanced-vision-01-o2-c1', 'mission-ai-advanced-vision-01-o2', 1, 'investigation', 'Cipher Division is deciding how to train a hazard detector. Which evidence justifies using transfer learning instead of training from scratch?', '{"evidence":[{"id":"e1","label":"Hazard image archive","detail":"Only 340 labeled hazard images exist across all of Cipher Labs'' camera history"},{"id":"e2","label":"Compute log","detail":"Cipher Labs has ample GPU capacity available overnight"},{"id":"e3","label":"Pretrained model catalog","detail":"Several models trained on millions of general images are available and unrelated to reactors"}],"question":"Which evidence justifies using transfer learning instead of training from scratch?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-advanced-vision-02-o1-c1', 'mission-ai-advanced-vision-02-o1', 1, 'multiple_choice', 'What do the early layers of a pretrained vision model typically learn?', '{"question":"What do the early layers of a pretrained vision model typically learn?","options":[{"id":"a","text":"Specific hazard categories"},{"id":"b","text":"Generic visual features like edges, textures and shapes"},{"id":"c","text":"The exact training labels"},{"id":"d","text":"Nothing, they remain random"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-advanced-vision-02-o2-c1', 'mission-ai-advanced-vision-02-o2', 1, 'drag_and_drop', 'Sort each statement into early layers (general) or late layers (task-specific).', '{"items":[{"id":"i1","text":"Detect edges and simple textures"},{"id":"i2","text":"Recognize the specific 1,000 ImageNet categories"},{"id":"i3","text":"Respond to color gradients and corners"},{"id":"i4","text":"Map high-level features to the original dataset''s exact output classes"}],"targets":[{"id":"t1","label":"Early layers (general)"},{"id":"t2","label":"Late layers (task-specific)"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-advanced-vision-03-o1-c1', 'mission-ai-advanced-vision-03-o1', 1, 'interactive_diagram', 'Order the steps of fine-tuning a pretrained model.', '{"diagramId":"fine-tuning-steps","hotspots":[{"id":"h1","label":"Load a pretrained model and its learned weights","explanation":"Fine-tuning starts from an already-trained network, not a blank one."},{"id":"h2","label":"Freeze the early general-feature layers","explanation":"Keep the generic edge/texture/shape knowledge intact by preventing it from being overwritten early on."},{"id":"h3","label":"Replace the final layer(s) with a new head for your task","explanation":"The original output classes are swapped for the categories the new task actually needs."},{"id":"h4","label":"Train on your own labeled data at a low learning rate","explanation":"Small, careful updates adapt the model without erasing what it already knows."},{"id":"h5","label":"Optionally unfreeze deeper layers and continue training carefully","explanation":"With enough data, later layers can be allowed to adjust too, still at a low learning rate."}],"task":"Order the fine-tuning steps from first to last."}'::jsonb, '{"correctOrderIds":["h1","h2","h3","h4","h5"]}'::jsonb),
  ('mission-ai-advanced-vision-03-o2-c1', 'mission-ai-advanced-vision-03-o2', 1, 'multiple_choice', 'What is catastrophic forgetting during fine-tuning?', '{"question":"What is catastrophic forgetting during fine-tuning?","options":[{"id":"a","text":"The model runs out of disk space"},{"id":"b","text":"Fine-tuning too aggressively erases the general knowledge the pretrained model started with"},{"id":"c","text":"The model forgets to save checkpoints"},{"id":"d","text":"The training loop crashes"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-advanced-vision-04-o1-c1', 'mission-ai-advanced-vision-04-o1', 1, 'multiple_choice', 'What does an object detector output for an image that a plain classifier does not?', '{"question":"What does an object detector output for an image that a plain classifier does not?","options":[{"id":"a","text":"A single label for the whole image"},{"id":"b","text":"One or more bounding boxes, each with its own class label and confidence score"},{"id":"c","text":"A compressed version of the image"},{"id":"d","text":"The image''s file size"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-advanced-vision-04-o2-c1', 'mission-ai-advanced-vision-04-o2', 1, 'drag_and_drop', 'Sort each output into classifier output or detector output.', '{"items":[{"id":"i1","text":"Single label: hazard present"},{"id":"i2","text":"Bounding box at (120,80)-(210,150), label crack, confidence 0.94"},{"id":"i3","text":"Single label: no hazard"},{"id":"i4","text":"Three separate bounding boxes, each with its own label and confidence"}],"targets":[{"id":"t1","label":"Classifier output"},{"id":"t2","label":"Detector output"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-advanced-vision-05-o1-c1', 'mission-ai-advanced-vision-05-o1', 1, 'multiple_choice', 'A bounding box is most commonly represented as...', '{"question":"A bounding box is most commonly represented as...","options":[{"id":"a","text":"A single center pixel"},{"id":"b","text":"x, y, width, height (or equivalent corner coordinates)"},{"id":"c","text":"A text description"},{"id":"d","text":"A percentage of the image''s file size"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-advanced-vision-05-o2-c1', 'mission-ai-advanced-vision-05-o2', 1, 'investigation', 'A detector for Cipher Labs draws boxes that appear correct in testing but land in the wrong place in production. Which evidence explains why?', '{"evidence":[{"id":"e1","label":"Coordinate log","detail":"Training used (x,y) measured from the image''s top-left corner; the deployment pipeline was reading coordinates as measured from the bottom-left corner"},{"id":"e2","label":"Model accuracy report","detail":"Detector scored 92% on the held-out test set"},{"id":"e3","label":"Camera firmware log","detail":"Cameras were recently updated to a higher resolution"}],"question":"Which evidence explains why boxes correct in testing land in the wrong place in production?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-advanced-vision-06-o1-c1', 'mission-ai-advanced-vision-06-o1', 1, 'multiple_choice', 'IoU is calculated as...', '{"question":"IoU is calculated as...","options":[{"id":"a","text":"Overlap area minus total area"},{"id":"b","text":"Overlap area divided by the total area covered by both boxes combined"},{"id":"c","text":"The distance between box centers"},{"id":"d","text":"The ratio of box widths"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-advanced-vision-06-o2-c1', 'mission-ai-advanced-vision-06-o2', 1, 'investigation', 'Cipher Division needs one prediction to count as a confirmed hazard detection, using a typical 0.5 IoU threshold. Which box clears it?', '{"evidence":[{"id":"e1","label":"Box A","detail":"Predicted box overlaps the true hazard box almost completely; IoU = 0.91"},{"id":"e2","label":"Box B","detail":"Predicted box barely touches the true hazard box; IoU = 0.08"},{"id":"e3","label":"Box C","detail":"Predicted box covers a completely different, hazard-free region; IoU = 0.0"}],"question":"Which box clears a typical 0.5 IoU threshold?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-advanced-vision-07-o1-c1', 'mission-ai-advanced-vision-07-o1', 1, 'drag_and_drop', 'Match each term to what it describes.', '{"items":[{"id":"i1","text":"A predicted box that matches a real hazard above the IoU threshold, correct class"},{"id":"i2","text":"A predicted box with no matching real hazard"},{"id":"i3","text":"A real hazard the model never predicted a box for at all"},{"id":"i4","text":"Of everything the model flagged as a hazard, the fraction that was actually real"},{"id":"i5","text":"Of every real hazard that existed, the fraction the model actually found"}],"targets":[{"id":"t1","label":"True Positive"},{"id":"t2","label":"False Positive"},{"id":"t3","label":"False Negative"},{"id":"t4","label":"Precision"},{"id":"t5","label":"Recall"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4","i5":"t5"}}'::jsonb),
  ('mission-ai-advanced-vision-07-o2-c1', 'mission-ai-advanced-vision-07-o2', 1, 'multiple_choice', 'A detector that finds every real hazard but also raises many false alarms has...', '{"question":"A detector that finds every real hazard but also raises many false alarms has...","options":[{"id":"a","text":"High recall, low precision"},{"id":"b","text":"High precision, low recall"},{"id":"c","text":"High precision and high recall"},{"id":"d","text":"Low recall and low precision"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-ai-advanced-vision-08-o1-c1', 'mission-ai-advanced-vision-08-o1', 1, 'multiple_choice', 'What does segmentation predict that a bounding box does not?', '{"question":"What does segmentation predict that a bounding box does not?","options":[{"id":"a","text":"A confidence score"},{"id":"b","text":"A class label for every individual pixel, tracing the object''s actual shape"},{"id":"c","text":"The image''s file format"},{"id":"d","text":"The camera''s frame rate"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-advanced-vision-08-o2-c1', 'mission-ai-advanced-vision-08-o2', 1, 'investigation', 'A rectangular bounding box around a diagonal crack includes a lot of background pixels the crack itself does not occupy. Which evidence best explains why segmentation would measure the crack''s extent more accurately?', '{"evidence":[{"id":"e1","label":"Box overlap analysis","detail":"The bounding box only overlaps the true crack pixels by 35 percent; the rest of the box is undamaged surface"},{"id":"e2","label":"Detection confidence","detail":"The bounding box detection had 97 percent confidence"},{"id":"e3","label":"Camera metadata","detail":"Image was captured at 4K resolution"}],"question":"Which evidence best explains why segmentation would measure the crack''s extent more accurately than the box?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-advanced-vision-09-o1-c1', 'mission-ai-advanced-vision-09-o1', 1, 'drag_and_drop', 'Sort each scenario into semantic segmentation or instance segmentation.', '{"items":[{"id":"i1","text":"Coloring every damaged pixel in a frame the same color, without counting how many separate cracks exist"},{"id":"i2","text":"Outlining crack one and crack two separately, even though they touch, so each can be counted and measured on its own"},{"id":"i3","text":"Answering what fraction of this wall is corroded"},{"id":"i4","text":"Answering how many distinct corrosion patches are on this wall"}],"targets":[{"id":"t1","label":"Semantic segmentation"},{"id":"t2","label":"Instance segmentation"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),
  ('mission-ai-advanced-vision-09-o2-c1', 'mission-ai-advanced-vision-09-o2', 1, 'multiple_choice', 'Cipher Division wants to know exactly how many separate fractures exist in one frame, each measured on its own. Which approach is required?', '{"question":"Cipher Division wants to know exactly how many separate fractures exist in one frame, each measured on its own. Which approach is required?","options":[{"id":"a","text":"Semantic segmentation"},{"id":"b","text":"Instance segmentation"},{"id":"c","text":"A single whole-image classifier"},{"id":"d","text":"Bounding boxes alone, with no segmentation"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-advanced-vision-10-o1-c1', 'mission-ai-advanced-vision-10-o1', 1, 'multiple_choice', 'An image embedding is best described as...', '{"question":"An image embedding is best described as...","options":[{"id":"a","text":"A compressed JPEG file"},{"id":"b","text":"A numerical vector representing an image, positioned so similar images land near each other in that vector space"},{"id":"c","text":"The raw pixel grid"},{"id":"d","text":"A bounding box coordinate"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-advanced-vision-10-o2-c1', 'mission-ai-advanced-vision-10-o2', 1, 'investigation', 'Cipher Division wants to find every past camera frame that looks similar to a newly flagged hazard frame, without re-labeling the entire archive. Which evidence shows embeddings can solve this?', '{"evidence":[{"id":"e1","label":"Embedding search test","detail":"Nearest neighbors to the new hazard frame''s embedding are frames showing visually similar stress fractures, despite none of them sharing a filename or timestamp"},{"id":"e2","label":"Storage report","detail":"The camera archive is several terabytes"},{"id":"e3","label":"Detector accuracy","detail":"The detection model scores 90 percent average precision"}],"question":"Which evidence shows embeddings can retrieve visually similar past frames?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-advanced-vision-11-o1-c1', 'mission-ai-advanced-vision-11-o1', 1, 'multiple_choice', 'What is the key mechanism a Vision Transformer uses that a CNN does not?', '{"question":"What is the key mechanism a Vision Transformer uses that a CNN does not?","options":[{"id":"a","text":"Convolutional kernels sliding over pixels"},{"id":"b","text":"Self-attention across image patches, letting any patch relate directly to any other patch"},{"id":"c","text":"Pooling layers"},{"id":"d","text":"A fixed lookup table of labels"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-advanced-vision-11-o2-c1', 'mission-ai-advanced-vision-11-o2', 1, 'drag_and_drop', 'Sort each property into CNN or Vision Transformer.', '{"items":[{"id":"i1","text":"Builds understanding through local convolution filters applied layer by layer"},{"id":"i2","text":"Splits the image into patches and relates them through self-attention"},{"id":"i3","text":"Generally needs less data to train well from scratch"},{"id":"i4","text":"Generally needs more data to reach the same performance from scratch"}],"targets":[{"id":"t1","label":"CNN"},{"id":"t2","label":"Vision Transformer"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-advanced-vision-12-o1-c1', 'mission-ai-advanced-vision-12-o1', 1, 'investigation', 'Which sweep result shows a well-localized, genuinely correct detection?', '{"evidence":[{"id":"e1","label":"Camera Bay 4 result","detail":"Predicted box IoU against the confirmed fracture location: 0.87"},{"id":"e2","label":"Camera Bay 11 result","detail":"Predicted box IoU against a labeled clean panel: 0.06, correctly low"},{"id":"e3","label":"Camera Bay 7 result","detail":"Predicted box drawn but IoU against nearest real feature: 0.02, no genuine damage at that location"}],"question":"Which result shows a well-localized, genuinely correct detection?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-advanced-vision-12-o2-c1', 'mission-ai-advanced-vision-12-o2', 1, 'investigation', 'Which result is the strongest evidence the detector is finding genuine, physically confirmed hazards rather than noise?', '{"evidence":[{"id":"e1","label":"Bay 4 detection","detail":"IoU 0.87 against a fracture independently confirmed by a follow-up physical inspection -- true positive"},{"id":"e2","label":"Bay 9 detection","detail":"Box drawn over a shadow cast by scaffolding; follow-up inspection found no damage -- false positive"},{"id":"e3","label":"Bay 15 result","detail":"No box was drawn here, but follow-up inspection found a hairline stress fracture the detector missed -- false negative"}],"question":"Which result is the strongest evidence the detector is finding genuine hazards rather than noise?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-advanced-vision-12-o3-c1', 'mission-ai-advanced-vision-12-o3', 1, 'investigation', 'What does the sweep actually confirm about the scope of the damage?', '{"evidence":[{"id":"e1","label":"Sweep summary","detail":"Across the full facility sweep, five separate locations scored true positive against independent physical inspection: the original fracture plus four more, in different reactor bays"},{"id":"e2","label":"False alarm count","detail":"Twelve boxes were drawn that follow-up inspection ruled out as false positives"},{"id":"e3","label":"Camera uptime log","detail":"All cameras in the sweep were online and recording for the full inspection window"}],"question":"What does the sweep actually confirm about the scope of the damage?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-advanced-vision-12-o4-c1', 'mission-ai-advanced-vision-12-o4', 1, 'boss_encounter', 'Having graded box quality, separated real detections from noise, and checked the full sweep, state what Cipher Division now knows about the facility''s physical damage.', '{"stages":[{"objectiveRef":"mission-ai-advanced-vision-12-o1","label":"Judge box quality"},{"objectiveRef":"mission-ai-advanced-vision-12-o2","label":"Separate true detections from noise"},{"objectiveRef":"mission-ai-advanced-vision-12-o3","label":"Confirm the hazards are not isolated"}],"task":"State the finding in one sentence: a fine-tuned detector correctly localizes hazards, its positive detections are physically confirmed, and the original fracture was never an isolated incident."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-advanced-vision-12-o1","mission-ai-advanced-vision-12-o2","mission-ai-advanced-vision-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-advanced-vision-01-o1-c1', 'orientation', 'Think about what last Act''s classifier actually output: a single answer for the whole picture.', 10, 1),
  ('mission-ai-advanced-vision-01-o1-c1', 'solution', 'It tells you a hazard exists somewhere in the frame, but never says where -- localization is the missing piece.', 20, 2),
  ('mission-ai-advanced-vision-01-o2-c1', 'orientation', 'Look for the evidence about how much labeled data actually exists, not about compute or model availability.', 10, 1),
  ('mission-ai-advanced-vision-01-o2-c1', 'solution', 'e1: only 340 labeled hazard images exist -- nowhere near enough to train a detector from scratch, which is exactly the gap transfer learning closes.', 20, 2),

  ('mission-ai-advanced-vision-02-o1-c1', 'orientation', 'Early layers process raw pixels first, before any concept of a specific category could exist yet.', 10, 1),
  ('mission-ai-advanced-vision-02-o1-c1', 'solution', 'Early layers learn generic visual building blocks -- edges, textures, shapes -- not specific categories.', 20, 2),
  ('mission-ai-advanced-vision-02-o2-c1', 'orientation', 'Ask whether a statement is about a low-level visual pattern or about a specific named category.', 10, 1),
  ('mission-ai-advanced-vision-02-o2-c1', 'concept', 'Generic patterns like edges and gradients belong to the early layers; anything tied to the original dataset''s specific output classes belongs to the late layers.', 20, 2),
  ('mission-ai-advanced-vision-02-o2-c1', 'solution', 'Early (general): detecting edges and textures, responding to color gradients and corners. Late (task-specific): recognizing the exact 1,000 ImageNet categories, mapping to the original output classes.', 30, 3),

  ('mission-ai-advanced-vision-03-o1-c1', 'orientation', 'Nothing can be trained on your own data until the pretrained model and its weights are actually loaded first.', 10, 1),
  ('mission-ai-advanced-vision-03-o1-c1', 'concept', 'The new task-specific head has to exist before training on your own labeled data can happen -- and freezing decisions come before that training step, not after.', 20, 2),
  ('mission-ai-advanced-vision-03-o1-c1', 'solution', 'Load the pretrained model, freeze the early layers, replace the final layer(s) with a new head, train on your own data at a low learning rate, then optionally unfreeze deeper layers and continue carefully.', 30, 3),
  ('mission-ai-advanced-vision-03-o2-c1', 'orientation', 'The failure is about knowledge being lost, not about hardware or storage.', 10, 1),
  ('mission-ai-advanced-vision-03-o2-c1', 'solution', 'Catastrophic forgetting: fine-tuning too aggressively erases the general knowledge the pretrained model started with.', 20, 2),

  ('mission-ai-advanced-vision-04-o1-c1', 'orientation', 'A classifier outputs one thing per image. Think about what changes when the model has to say where as well as what.', 10, 1),
  ('mission-ai-advanced-vision-04-o1-c1', 'solution', 'A detector outputs one or more bounding boxes, each carrying its own class label and confidence score.', 20, 2),
  ('mission-ai-advanced-vision-04-o2-c1', 'orientation', 'A single label covering the whole image belongs to a classifier. Anything with box coordinates belongs to a detector.', 10, 1),
  ('mission-ai-advanced-vision-04-o2-c1', 'solution', 'Classifier output: a single whole-image label, whether hazard present or no hazard. Detector output: one or more individual bounding boxes, each with its own label and confidence.', 20, 2),

  ('mission-ai-advanced-vision-05-o1-c1', 'orientation', 'Think about the minimum numbers needed to pin down a rectangle''s position and size.', 10, 1),
  ('mission-ai-advanced-vision-05-o1-c1', 'solution', 'x, y, width, height (or two opposite corners) is the standard bounding box representation.', 20, 2),
  ('mission-ai-advanced-vision-05-o2-c1', 'orientation', 'The bug is not about the model''s accuracy score -- look for a mismatch in how coordinates are defined.', 10, 1),
  ('mission-ai-advanced-vision-05-o2-c1', 'solution', 'e1: training measured coordinates from the top-left corner, but deployment read them as bottom-left -- the convention mismatch silently misplaces every box.', 20, 2),

  ('mission-ai-advanced-vision-06-o1-c1', 'orientation', 'IoU compares the overlap between two boxes to how much total space they occupy together.', 10, 1),
  ('mission-ai-advanced-vision-06-o1-c1', 'solution', 'IoU equals overlap area divided by the total area covered by both boxes combined.', 20, 2),
  ('mission-ai-advanced-vision-06-o2-c1', 'orientation', 'Compare each IoU value to the typical 0.5 threshold used to call something a real hit.', 10, 1),
  ('mission-ai-advanced-vision-06-o2-c1', 'solution', 'e1: IoU 0.91 clears any typical threshold by a wide margin -- a genuinely well-localized detection.', 20, 2),

  ('mission-ai-advanced-vision-07-o1-c1', 'orientation', 'Match each definition to whether it describes a correct box, a wrong box, a missed hazard, or one of the two summary rates.', 10, 1),
  ('mission-ai-advanced-vision-07-o1-c1', 'concept', 'True positive, false positive and false negative describe individual predictions. Precision and recall describe rates computed across all of them.', 20, 2),
  ('mission-ai-advanced-vision-07-o1-c1', 'solution', 'True positive: matches a real hazard above threshold, correct class. False positive: no matching real hazard. False negative: a real hazard never predicted at all. Precision: fraction of positive predictions that were correct. Recall: fraction of real hazards actually found.', 30, 3),
  ('mission-ai-advanced-vision-07-o2-c1', 'orientation', 'Finding every real hazard is about recall. Raising many false alarms is about precision.', 10, 1),
  ('mission-ai-advanced-vision-07-o2-c1', 'solution', 'Finding every hazard but also raising many false alarms is exactly high recall, low precision.', 20, 2),

  ('mission-ai-advanced-vision-08-o1-c1', 'orientation', 'Think about the finest level of detail a model could possibly label -- smaller than a whole rectangle.', 10, 1),
  ('mission-ai-advanced-vision-08-o1-c1', 'solution', 'Segmentation predicts a class label for every individual pixel, tracing the object''s actual shape.', 20, 2),
  ('mission-ai-advanced-vision-08-o2-c1', 'orientation', 'Look for the evidence that directly measures how much of the box is actually crack versus background.', 10, 1),
  ('mission-ai-advanced-vision-08-o2-c1', 'solution', 'e1: the box only overlaps true crack pixels by 35 percent -- most of the box is undamaged surface, which is exactly what segmentation would avoid including.', 20, 2),

  ('mission-ai-advanced-vision-09-o1-c1', 'orientation', 'Ask whether the scenario needs to separate individual objects, or just label pixels by category overall.', 10, 1),
  ('mission-ai-advanced-vision-09-o1-c1', 'concept', 'If the question is how much, it is usually semantic. If the question is how many, each measured separately, it is instance.', 20, 2),
  ('mission-ai-advanced-vision-09-o1-c1', 'solution', 'Semantic: coloring all damaged pixels the same, answering what fraction is corroded. Instance: outlining each crack separately even when touching, answering how many distinct patches.', 30, 3),
  ('mission-ai-advanced-vision-09-o2-c1', 'orientation', 'Counting distinct objects, each measured on its own, needs more than category-level labeling.', 10, 1),
  ('mission-ai-advanced-vision-09-o2-c1', 'solution', 'Instance segmentation is required to count and measure each separate fracture individually.', 20, 2),

  ('mission-ai-advanced-vision-10-o1-c1', 'orientation', 'An embedding is not the image file itself -- it is what the model reduces the image to internally.', 10, 1),
  ('mission-ai-advanced-vision-10-o1-c1', 'solution', 'An image embedding is a numerical vector positioned so that similar images land near each other in that vector space.', 20, 2),
  ('mission-ai-advanced-vision-10-o2-c1', 'orientation', 'Look for the evidence that actually demonstrates similar-looking frames landing close together, not evidence about storage or accuracy.', 10, 1),
  ('mission-ai-advanced-vision-10-o2-c1', 'solution', 'e1: nearest neighbors to the new frame''s embedding are visually similar past fractures, despite no shared filename or timestamp -- proof the embedding space itself encodes visual similarity.', 20, 2),

  ('mission-ai-advanced-vision-11-o1-c1', 'orientation', 'Think about what replaces the sliding convolution filter in a transformer-based architecture.', 10, 1),
  ('mission-ai-advanced-vision-11-o1-c1', 'solution', 'Self-attention across image patches -- letting any patch relate directly to any other patch -- is the key ViT mechanism.', 20, 2),
  ('mission-ai-advanced-vision-11-o2-c1', 'orientation', 'Local filters applied layer by layer belong to one architecture; patches related through attention belong to the other.', 10, 1),
  ('mission-ai-advanced-vision-11-o2-c1', 'concept', 'The architecture that needs less data from scratch is the older, more locally-constrained one.', 20, 2),
  ('mission-ai-advanced-vision-11-o2-c1', 'solution', 'CNN: local convolution filters layer by layer, generally needs less data from scratch. Vision Transformer: patches related via self-attention, generally needs more data from scratch to match CNN performance.', 30, 3),

  ('mission-ai-advanced-vision-12-o1-c1', 'orientation', 'Look for the result whose IoU is measured against the confirmed fracture location itself, and is high.', 10, 1),
  ('mission-ai-advanced-vision-12-o1-c1', 'solution', 'e1: IoU 0.87 against the confirmed fracture location is a well-localized, genuinely correct detection.', 20, 2),
  ('mission-ai-advanced-vision-12-o2-c1', 'orientation', 'The strongest proof is a detection independently confirmed by a physical follow-up inspection, not just a high IoU alone.', 10, 1),
  ('mission-ai-advanced-vision-12-o2-c1', 'solution', 'e1: IoU 0.87 against a fracture independently confirmed by physical inspection is a true positive -- the strongest evidence of a genuine detection.', 20, 2),
  ('mission-ai-advanced-vision-12-o3-c1', 'orientation', 'Look for the evidence that counts confirmed hazards across the whole sweep, not just false alarms or camera uptime.', 10, 1),
  ('mission-ai-advanced-vision-12-o3-c1', 'solution', 'e1: five separate locations, including the original fracture, scored true positive against independent physical inspection -- the damage is not isolated.', 20, 2),
  ('mission-ai-advanced-vision-12-o4-c1', 'orientation', 'Combine what the box quality, the true-positive evidence, and the sweep-wide count each proved.', 15, 1),
  ('mission-ai-advanced-vision-12-o4-c1', 'solution', 'The fine-tuned detector localizes hazards accurately, its positive detections are physically confirmed rather than noise, and the sweep shows five genuine hazards across the facility -- the original fracture was never an isolated incident.', 25, 2);
